#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c/rtio.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/rtio/work.h>
#include <zephyr/sys/mpsc_lockfree.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(i2c_rtio, CONFIG_I2C_LOG_LEVEL);

const struct rtio_iodev_api i2c_iodev_api = {
	.submit = i2c_iodev_submit,
};

struct rtio_sqe *i2c_rtio_copy(struct rtio *r,
			       struct rtio_iodev *iodev,
			       const struct i2c_msg *msgs,
			       uint8_t num_msgs)
{
	__ASSERT(num_msgs > 0, "Expecting at least one message to copy");

	struct rtio_sqe *sqe = NULL;

	for (uint8_t i = 0; i < num_msgs; i++) {
		sqe = rtio_sqe_acquire(r);

		if (sqe == NULL) {
			rtio_sqe_drop_all(r);
			return NULL;
		}

		if (msgs[i].flags & I2C_MSG_READ) {
			rtio_sqe_prep_read(sqe, iodev, RTIO_PRIO_NORM,
					   msgs[i].buf, msgs[i].len,
					   NULL);
		} else {
			rtio_sqe_prep_write(sqe, iodev, RTIO_PRIO_NORM,
					    msgs[i].buf, msgs[i].len,
					    NULL);
		}
		sqe->flags |= RTIO_SQE_TRANSACTION;
		sqe->iodev_flags =
			((msgs[i].flags & I2C_MSG_STOP) ? RTIO_IODEV_I2C_STOP : 0) |
			((msgs[i].flags & I2C_MSG_RESTART) ? RTIO_IODEV_I2C_RESTART : 0) |
			((msgs[i].flags & I2C_MSG_ADDR_10_BITS) ? RTIO_IODEV_I2C_10_BITS : 0);
	}

	sqe->flags &= ~RTIO_SQE_TRANSACTION;

	return sqe;
}

struct rtio_sqe *i2c_rtio_copy_reg_write_byte(struct rtio *r,
					      struct rtio_iodev *iodev,
					      uint8_t reg_addr,
					      uint8_t data)
{
	struct rtio_sqe *sqe = rtio_sqe_acquire(r);
	struct i2c_msg msg;

	if (sqe == NULL) {
		return NULL;
	}

	/* Similar to how syntactic sugar function: i2c_reg_write_byte
	 * wraps the operation as single message starting with two bytes.
	 */
	uint8_t tx_buf[2] = {reg_addr, data};

	msg.buf = tx_buf;
	msg.len = sizeof(tx_buf);
	msg.flags = I2C_MSG_WRITE | I2C_MSG_STOP;

	rtio_sqe_prep_tiny_write(sqe, iodev, RTIO_PRIO_NORM, msg.buf, msg.len, NULL);
	sqe->iodev_flags = RTIO_IODEV_I2C_STOP;

	return sqe;
}

struct rtio_sqe *i2c_rtio_copy_reg_burst_read(struct rtio *r,
					      struct rtio_iodev *iodev,
					      uint8_t start_addr,
					      void *buf,
					      size_t num_bytes)
{
	struct i2c_msg msgs[2];
	struct rtio_sqe *sqe;

	sqe = rtio_sqe_acquire(r);
	if (sqe == NULL) {
		return NULL;
	}

	/* Similar to how syntactic sugar function: i2c_burst_read
	 * wraps the operation as two messages.
	 */
	msgs[0].buf = &start_addr;
	msgs[0].len = 1U;
	msgs[0].flags = I2C_MSG_WRITE;

	rtio_sqe_prep_tiny_write(sqe, iodev, RTIO_PRIO_NORM,
				 msgs[0].buf, msgs[0].len, NULL);
	sqe->flags |= RTIO_SQE_TRANSACTION;

	msgs[1].buf = buf;
	msgs[1].len = num_bytes;
	msgs[1].flags = I2C_MSG_RESTART | I2C_MSG_READ | I2C_MSG_STOP;

	sqe = i2c_rtio_copy(r, iodev, &msgs[1], 1);
	if (sqe == NULL) {
		return NULL;
	}

	/* Clear the last transaction flag */
	sqe->flags &= ~RTIO_SQE_TRANSACTION;

	return sqe;
}

static void i2c_iodev_submit_work_handler(struct rtio_iodev_sqe *txn_first)
{
	struct i2c_dt_spec *dt_spec = txn_first->sqe.iodev->data;
	const struct device *dev = dt_spec->bus;

	LOG_DBG("Sync RTIO work item for: %p", (void *)txn_first);

	uint32_t num_msgs = 0;
	int rc = 0;
	struct rtio_iodev_sqe *txn_last = txn_first;

	/* Count the number of messages in the transaction so we can
	 * allocate the array of messages on the stack.
	 */
	do {
		switch (txn_last->sqe.op) {
		case RTIO_OP_RX:
		case RTIO_OP_TX:
		case RTIO_OP_TINY_TX:
			num_msgs++;
			break;
		default:
			LOG_ERR("Invalid op code %d for submission %p\n",
				txn_last->sqe.op, (void *)&txn_last->sqe);
			rc = -EIO;
			break;
		}
		txn_last = rtio_txn_next(txn_last);
	} while (rc == 0 && txn_last != NULL);

	if (rc != 0) {
		rtio_iodev_sqe_err(txn_first, rc);
		return;
	}

	/* Allocate the msgs on the stack, MISRA doesn't like VLAs so we need
	 * a maximum number of messages here. We'll use
	 * CONFIG_I2C_RTIO_FALLBACK_MSGS.
	 */
	if (num_msgs > CONFIG_I2C_RTIO_FALLBACK_MSGS) {
		LOG_ERR("At most CONFIG_I2C_RTIO_FALLBACK_MSGS" "(%d)"
			" submissions in a transaction are allowed in the default handler",
			CONFIG_I2C_RTIO_FALLBACK_MSGS);
		rtio_iodev_sqe_err(txn_first, -ENOMEM);
		return;
	}
	struct i2c_msg msgs[CONFIG_I2C_RTIO_FALLBACK_MSGS];

	/* Initialize the messages and send the transfer */
	txn_last = txn_first;
	for (int i = 0; i < num_msgs; i++) {
		switch (txn_last->sqe.op) {
		case RTIO_OP_RX:
			msgs[i].buf = txn_last->sqe.rx.buf;
			msgs[i].len = txn_last->sqe.rx.buf_len;
			msgs[i].flags = I2C_MSG_READ;
			break;
		case RTIO_OP_TX:
			msgs[i].buf = (uint8_t *)txn_last->sqe.tx.buf;
			msgs[i].len = txn_last->sqe.tx.buf_len;
			msgs[i].flags = I2C_MSG_WRITE;
			break;
		case RTIO_OP_TINY_TX:
			msgs[i].buf = (uint8_t *)txn_last->sqe.tiny_tx.buf;
			msgs[i].len = txn_last->sqe.tiny_tx.buf_len;
			msgs[i].flags = I2C_MSG_WRITE;
			break;
		default:
			rc = -EIO;
			break;
		}
		msgs[i].flags |=
			((txn_last->sqe.iodev_flags & RTIO_IODEV_I2C_STOP) ? I2C_MSG_STOP : 0) |
			((txn_last->sqe.iodev_flags & RTIO_IODEV_I2C_RESTART) ?
				I2C_MSG_RESTART : 0) |
			((txn_last->sqe.iodev_flags & RTIO_IODEV_I2C_10_BITS) ?
				I2C_MSG_ADDR_10_BITS : 0);

		txn_last = rtio_txn_next(txn_last);
	}

	if (rc == 0) {
		__ASSERT_NO_MSG(num_msgs > 0);

		rc = i2c_transfer(dev, msgs, num_msgs, dt_spec->addr);
	}

	if (rc != 0) {
		rtio_iodev_sqe_err(txn_first, rc);
	} else {
		rtio_iodev_sqe_ok(txn_first, 0);
	}
}

void i2c_iodev_submit_fallback(const struct device *dev, struct rtio_iodev_sqe *iodev_sqe)
{
	LOG_DBG("Executing fallback for dev: %p, sqe: %p", (void *)dev, (void *)iodev_sqe);

	struct rtio_work_req *req = rtio_work_req_alloc();

	if (req == NULL) {
		rtio_iodev_sqe_err(iodev_sqe, -ENOMEM);
		return;
	}

	rtio_work_req_submit(req, iodev_sqe, i2c_iodev_submit_work_handler);
}

void i2c_rtio_init(struct i2c_rtio *ctx)
{
	k_sem_init(&ctx->lock, 1, 1);
	mpsc_init(&ctx->io_q);
	ctx->txn_head = NULL;
	ctx->txn_curr = NULL;
	ctx->dt_spec.bus = NULL;
	ctx->iodev.data = &ctx->dt_spec;
	ctx->iodev.api = &i2c_iodev_api;
}

/**
 * @brief Complete the current transaction (Wait for start/stop Included)
 *
 * @retval true If a new transaction is ready to start immediately
 * @retval false If no more transactions are left on the queue
 */
bool i2c_rtio_complete(struct i2c_rtio *ctx, int status)
{
	/* On error, bail across all the transactions */
	if (status < 0) {
		rtio_iodev_sqe_err(ctx->txn_head, status);
		return i2c_rtio_next(ctx, false);
	}

	/* Try to move on to the next message in the multi-msg transaction */
	if (i2c_rtio_next(ctx, true)) {
		return true;
	}

	rtio_iodev_sqe_ok(ctx->txn_head, status);
	return i2c_rtio_next(ctx, false);
}

/**
 * @brief Move on to the next transaction or transaction piece
 *
 * @retval true If a new transaction, or part of one, is ready to start
 * @retval false If no more transactions are left on the queue
 */
bool i2c_rtio_next(struct i2c_rtio *ctx, bool completion)
{
	k_sem_take(&ctx->lock, K_FOREVER);

	/* Already working on something, bail early */
	if (!completion && ctx->txn_head != NULL) {
		k_sem_give(&ctx->lock);
		return false;
	}

	if (completion && ctx->txn_curr != NULL) {
		ctx->txn_curr = rtio_txn_next(ctx->txn_curr);

		/* We have another part of the same transaction to process */
		if (ctx->txn_curr != NULL) {
			k_sem_give(&ctx->lock);
			return true;
		}
	}

	struct mpsc_node *next = mpsc_pop(&ctx->io_q);

	/* We have another entirely new transaction in the queue */
	if (next != NULL) {
		struct rtio_iodev_sqe *next_sqe =
			CONTAINER_OF(next, struct rtio_iodev_sqe, q);

		ctx->txn_head = next_sqe;
		ctx->txn_curr = next_sqe;
		k_sem_give(&ctx->lock);
		return true;
	}

	/* Completely done with the queue for now */
	ctx->txn_head = NULL;
	ctx->txn_curr = NULL;
	k_sem_give(&ctx->lock);
	return false;
}

bool i2c_rtio_submit(struct i2c_rtio *ctx, struct rtio_iodev_sqe *iodev_sqe)
{
	mpsc_push(&ctx->io_q, &iodev_sqe->q);
	return i2c_rtio_next(ctx, false);
}

int i2c_rtio_transfer(struct i2c_rtio *ctx, struct i2c_msg *msgs, uint8_t num_msgs, uint16_t addr)
{
	struct rtio_iodev *iodev = &ctx->iodev;
	struct rtio * const r = ctx->r;
	struct rtio_sqe *sqe = NULL;
	struct rtio_cqe *cqe = NULL;
	int res = 0;

	k_sem_take(&ctx->lock, K_FOREVER);

	ctx->dt_spec.addr = addr;

	sqe = i2c_rtio_copy(r, iodev, msgs, num_msgs);
	if (sqe == NULL) {
		LOG_ERR("Not enough submission queue entries");
		res = -ENOMEM;
		goto out;
	}

	rtio_submit(r, 1);

	cqe = rtio_cqe_consume(r);
	while (cqe != NULL) {
		res = cqe->result;
		rtio_cqe_release(r, cqe);
		cqe = rtio_cqe_consume(r);
	}

out:
	k_sem_give(&ctx->lock);
	return res;
}

int i2c_rtio_Configure(struct i2c_rtio *ctx, uint32_t i2c_config)
{
	struct rtio_iodev *iodev = &ctx->iodev;
	struct rtio * const r = ctx->r;
	struct rtio_sqe *sqe = NULL;
	struct rtio_cqe *cqe = NULL;
	int res = 0;

	k_sem_take(&ctx->lock, K_FOREVER);

	sqe = rtio_sqe_acquire(r);
	if (sqe == NULL) {
		LOG_ERR("Not enough submission queue entries");
		res = -ENOMEM;
		goto out;
	}

	sqe->op = RTIO_OP_I2C_CONFIGURE;
	sqe->iodev = iodev;
	sqe->i2c_config = i2c_config;

	rtio_submit(r, 1);

	cqe = rtio_cqe_consume(r);
	res = cqe->result;
	rtio_cqe_release(r, cqe);

out:
	k_sem_give(&ctx->lock);
	return res;
}

int i2c_rtio_recover(struct i2c_rtio *ctx)
{
	struct rtio_iodev *iodev = &ctx->iodev;
	struct rtio * const r = ctx->r;
	struct rtio_sqe *sqe = NULL;
	struct rtio_cqe *cqe = NULL;
	int res = 0;

	k_sem_take(&ctx->lock, K_FOREVER);

	sqe = rtio_sqe_acquire(r);
	if (sqe == NULL) {
		LOG_ERR("Not enough submission queue entries");
		res = -ENOMEM;
		goto out;
	}

	sqe->op = RTIO_OP_I2C_RECOVER;
	sqe->iodev = iodev;

	rtio_submit(r, 1);

	cqe = rtio_cqe_consume(r);
	res = cqe->result;
	rtio_cqe_release(r, cqe);

out:
	k_sem_give(&ctx->lock);
	return res;
}
